package com.toabea.closet.common;
import lombok.*; import org.springframework.data.annotation.*; import org.springframework.data.mongodb.core.index.Indexed; import org.springframework.data.mongodb.core.mapping.Document; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
@Document("orders") @Getter @Setter @NoArgsConstructor public class Order { @Id private String id; @Indexed(unique=true) private String orderNumber; private String customerId; private String customerName; private String email; private String phone; private String address; private List<OrderItem> items=new ArrayList<>(); private BigDecimal subtotal; private BigDecimal feeAmount=BigDecimal.ZERO; private BigDecimal total; private String paymentMethod="CASH"; private String paymentReference; private String paymentStatus="PENDING"; private String status="NEW"; private String notificationStatus="PENDING"; private Instant createdAt=Instant.now(); private Instant updatedAt=Instant.now(); }
